describe('Task Deletion with Confirmation Dialog', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should delete a task after confirming the deletion', () => {
    // Setup: Create a task
    cy.get('[data-testid="task-input"]').type('Complete project report');
    cy.get('[data-testid="task-description"]').type('Write 500 words');
    cy.get('[data-testid="create-task-button"]').click();

    // Verify task exists
    cy.get('[data-testid="task-item"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('contain', 'Complete project report');

    // Click delete button
    cy.get('[data-testid="delete-task-button"]').click();

    // Verify confirmation dialog appears
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-dialog"]').should('contain', 'Are you sure you want to delete this task?');

    // Confirm deletion
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Verify task is deleted
    cy.get('[data-testid="task-item"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Task deleted successfully');
  });

  it('should cancel task deletion when user clicks cancel button', () => {
    // Setup: Create a task
    cy.get('[data-testid="task-input"]').type('Review pull requests');
    cy.get('[data-testid="task-description"]').type('Check for bugs');
    cy.get('[data-testid="create-task-button"]').click();

    // Verify task exists
    cy.get('[data-testid="task-item"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('contain', 'Review pull requests');

    // Click delete button
    cy.get('[data-testid="delete-task-button"]').click();

    // Verify confirmation dialog appears
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');

    // Cancel deletion
    cy.get('[data-testid="cancel-delete-button"]').click();

    // Verify task still exists
    cy.get('[data-testid="task-item"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('contain', 'Review pull requests');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
